session_start();
$departments = require __DIR__ . '/campus_departments.php';
$student = $_SESSION['current_student'] ?? ['name'=>'Guest','course'=>'-','year'=>'-'];
?>
<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Real GPS Map - DEBESMSCAT</title><link rel="stylesheet" href="assets/style.css"></head>
<body>
<div class="map-layout">
  <div class="topbar"><div>Hi, <strong><?= htmlspecialchars($student['name']) ?></strong> - <?= htmlspecialchars($student['course']) ?> <?= htmlspecialchars($student['year']) ?></div><div class="top-actions"><span class="badge" style="background:#FEE2E2;color:#B91C1C;border-color:#FECACA;">📍 Real GPS Mode - Need Location</span><a href="index.php" class="btn btn-light small">Exit</a></div></div>
  <div class="map-grid">
    <div class="panel"><h3>Quick Access</h3><input type="text" id="searchBox" placeholder="Search building..." onkeyup="filterBuildings()"><div id="quickList"></div><hr><div id="gpsStatusBox" style="background:#FEF2F2; border:1px solid #FECACA; border-radius:10px; padding:10px; font-size:11px;"><strong>GPS Status:</strong><div id="gpsStatus">Waiting for location...</div><div id="gpsCoords" style="font-family:monospace; margin-top:4px;"></div></div></div>
    <div class="panel map-panel">
      <div class="map-container" id="mapContainer"><div class="map-zoom-layer" id="mapZoomLayer"><img src="assets/campus_map.jpg" id="mapImg" alt="DEBESMSCAT Map"><svg id="roadSvg" viewBox="0 0 100 100" preserveAspectRatio="none"><path id="routePath" fill="none" stroke="#2563EB" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="2 1.5" opacity="0.9"/><path id="roadBase" fill="none" stroke="#9CA3AF" stroke-width="0.6" opacity="0.25"/></svg><div id="pins"></div><div id="navArrow" class="nav-arrow" style="display:none;"><div class="arrow-icon">➤</div><div class="arrow-pulse"></div></div></div><div class="map-zoom-controls" role="group" aria-label="Map zoom controls"><button type="button" class="map-zoom-button" onclick="zoomMap(0.2)" aria-label="Zoom in">+</button><button type="button" class="map-zoom-button" onclick="zoomMap(-0.2)" aria-label="Zoom out">−</button><button type="button" class="map-zoom-reset" onclick="resetMapZoom()">Reset</button></div></div>
      <div class="map-controls">
        <button onclick="enableRealGPS()" class="btn btn-green">📍 Start GPS Tracking</button>
        <span style="font-size:11px; color:#6B7280;">Arrow gagalaw lang pag naglakad ka talaga</span>
        <span class="map-zoom-level" id="mapZoomLevel">100%</span>
      </div>
      <div class="turn-info" id="turnInfo">Pindot Start GPS Tracking - allow location - tapos maglakad ka</div>
    </div>
    <div class="panel"><div id="destSelector"><h3>Select Destination</h3><select id="destSelect"><option value="">-- Select department and room --</option><?php foreach ($departments as $department): ?><?php if (!$department['rooms']): ?><option value="<?= htmlspecialchars($department['id'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($department['name'], ENT_QUOTES, 'UTF-8') ?></option><?php else: ?><optgroup label="<?= htmlspecialchars($department['name'], ENT_QUOTES, 'UTF-8') ?>"><?php foreach ($department['rooms'] as $room): ?><option value="<?= htmlspecialchars($department['id'] . '-room-' . $room['number'], ENT_QUOTES, 'UTF-8') ?>">Room <?= (int) $room['number'] ?></option><?php endforeach; ?></optgroup><?php endif; ?><?php endforeach; ?></select><button onclick="startNav()" class="btn btn-green full">Start Navigation →</button><div class="note">Real GPS: Arrow gagalaw lang pag naglalakad ka sa campus. Hindi yung PLAY na auto-move.</div></div><div id="navPanel" style="display:none;"><h3>Turn-by-Turn</h3><div id="turnList"></div><div class="distance"><span id="distLeft">0m</span> left • <span id="stepsCount">0 steps</span></div><button onclick="stopNav()" class="btn btn-red full">Stop</button></div><hr><div id="buildingInfo"></div></div>
  </div>
</div>
<script>
const DEPARTMENTS = <?= json_encode($departments, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
const ROAD_NODES={TOP:{x:45,y:8},EDU_J:{x:45,y:21},MID_J:{x:45,y:30},LIB_J:{x:47,y:65},MAIN_F:{x:55,y:73},SOUTH:{x:56,y:90}};
const EDGES=[["TOP","EDU_J"],["EDU_J","MID_J"],["MID_J","LIB_J"],["LIB_J","MAIN_F"],["MAIN_F","SOUTH"]];
const BUILDINGS=DEPARTMENTS.flatMap(department=>department.rooms.map(room=>{const id=`${department.id}-room-${room.number}`;ROAD_NODES[id]=room.pos;EDGES.push([department.connection,id]);return{id,name:`${department.name} - Room ${room.number}`,shortName:`${department.shortName} ${room.number}`,node:id,pos:room.pos,color:department.color,desc:`${department.desc} - Room ${room.number}`};}));
DEPARTMENTS.filter(department=>department.rooms.length===0).forEach(department=>{ROAD_NODES[department.node]=department.pos;EDGES.push([department.connection,department.node]);BUILDINGS.push({id:department.id,name:department.name,shortName:department.shortName,node:department.node,pos:department.pos,color:department.color,desc:department.desc});});
let currentPath=[],progress=0,watchId=null,lastPos=null,totalSteps=0;
let mapZoom=1;
function applyMapZoom(){document.getElementById('mapZoomLayer').style.transform=`scale(${mapZoom})`;document.getElementById('mapZoomLevel').textContent=`${Math.round(mapZoom*100)}%`;}
function zoomMap(change){mapZoom=Math.min(2.4,Math.max(1,Math.round((mapZoom+change)*10)/10));applyMapZoom();}
function resetMapZoom(){mapZoom=1;applyMapZoom();}
function drawRoadBase(){const base=document.getElementById('roadBase');let d="";EDGES.forEach(([a,b])=>{const A=ROAD_NODES[a],B=ROAD_NODES[b];d+=`M ${A.x} ${A.y} L ${B.x} ${B.y} `;});base.setAttribute('d',d);}drawRoadBase();
function renderPins(){const pinsDiv=document.getElementById('pins');const quickList=document.getElementById('quickList');pinsDiv.innerHTML="";quickList.innerHTML="";BUILDINGS.forEach(b=>{const pin=document.createElement('div');pin.className='pin';pin.style.left=b.pos.x+'%';pin.style.top=b.pos.y+'%';pin.title=b.name;pin.innerHTML=`<div class="pin-dot" style="background:${b.color}"></div><span>${b.shortName}</span>`;pin.onclick=()=>{document.getElementById('destSelect').value=b.id; startNav();};pinsDiv.appendChild(pin);const q=document.createElement('div');q.className='quick-item';q.innerHTML=`<strong>${b.name}</strong><button onclick="document.getElementById('destSelect').value='${b.id}';startNav()" class="btn btn-green small">Go</button>`;quickList.appendChild(q);});}renderPins();
function findPath(s,e){const dist={},prev={},vis=new Set();Object.keys(ROAD_NODES).forEach(n=>{dist[n]=Infinity;prev[n]=null;});dist[s]=0;while(vis.size<Object.keys(ROAD_NODES).length){let u=null,min=Infinity;for(let n in dist)if(!vis.has(n)&&dist[n]<min){min=dist[n];u=n;}if(!u||u===e)break;vis.add(u);EDGES.forEach(([a,b])=>{let v=null;if(a===u)v=b;if(b===u)v=a;if(!v||vis.has(v))return;const w=Math.hypot(ROAD_NODES[u].x-ROAD_NODES[v].x,ROAD_NODES[u].y-ROAD_NODES[v].y);if(dist[u]+w<dist[v]){dist[v]=dist[u]+w;prev[v]=u;}});}let p=[],cur=e;while(cur){p.unshift(cur);cur=prev[cur];if(p.length>20)break;}return p[0]!==s?[s,e]:p;}
function pathLen(p){let l=0;for(let i=0;i<p.length-1;i++){const a=ROAD_NODES[p[i]],b=ROAD_NODES[p[i+1]];l+=Math.hypot(a.x-b.x,a.y-b.y);}return l||1;}
function pointAt(p,t){const tot=pathLen(p),tar=tot*t;let acc=0;for(let i=0;i<p.length-1;i++){const a=ROAD_NODES[p[i]],b=ROAD_NODES[p[i+1]];const seg=Math.hypot(a.x-b.x,a.y-b.y);if(acc+seg>=tar){const r=(tar-acc)/seg;return{x:a.x+(b.x-a.x)*r,y:a.y+(b.y-a.y)*r,ang:Math.atan2(b.y-a.y,b.x-a.x)};}acc+=seg;}const last=ROAD_NODES[p[p.length-1]],prev=ROAD_NODES[p[p.length-2]];return{x:last.x,y:last.y,ang:prev?Math.atan2(last.y-prev.y,last.x-prev.x):0};}
function startNav(){const id=document.getElementById('destSelect').value;if(!id){alert('Pili muna ng department at room');return;}const d=BUILDINGS.find(b=>b.id===id);if(!d){alert('Hindi mahanap ang napiling room. Pumili ulit.');return;}currentPath=findPath("TOP",d.node);progress=0;document.getElementById('navPanel').style.display='block';document.getElementById('destSelector').style.display='none';let rd="";currentPath.forEach((n,i)=>{const p=ROAD_NODES[n];rd+=i===0?`M ${p.x} ${p.y} `:`L ${p.x} ${p.y} `;});document.getElementById('routePath').setAttribute('d',rd);updateArrow(0);document.getElementById('navArrow').style.display='block';}
function updateArrow(t){const pt=pointAt(currentPath,t);const a=document.getElementById('navArrow');a.style.left=pt.x+'%';a.style.top=pt.y+'%';a.style.transform=`translate(-50%,-50%) rotate(${pt.ang}rad)`;const rem=(1-t)*pathLen(currentPath);document.getElementById('distLeft').textContent=Math.round(rem*5)+'m';document.getElementById('turnInfo').textContent=`Progress ${Math.round(t*100)}% - naglalakad ka? ${totalSteps} steps detected`;}
function enableRealGPS(){if(!navigator.geolocation){alert('No GPS');return;}document.getElementById('gpsStatus').textContent='Tracking... Maglakad ka sa campus';if(watchId) navigator.geolocation.clearWatch(watchId);watchId=navigator.geolocation.watchPosition(pos=>{const {latitude,longitude,accuracy}=pos.coords;document.getElementById('gpsCoords').textContent=`Lat:${latitude.toFixed(5)} Lon:${longitude.toFixed(5)} ±${Math.round(accuracy)}m`;document.getElementById('gpsStatus').textContent='GPS active - gumagalaw ka ba?';if(lastPos){const dist=Math.hypot(latitude-lastPos.lat, longitude-lastPos.lon);if(dist>0.00002){progress=Math.min(1,progress+0.03);updateArrow(progress);totalSteps++;document.getElementById('stepsCount').textContent=totalSteps+' steps';}}lastPos={lat:latitude,lon:longitude};},err=>{document.getElementById('gpsStatus').textContent='Error: '+err.message+' - i-allow location';},{enableHighAccuracy:true,maximumAge:1000,timeout:10000});}
function stopNav(){if(watchId) navigator.geolocation.clearWatch(watchId);document.getElementById('navPanel').style.display='none';document.getElementById('destSelector').style.display='block';document.getElementById('routePath').setAttribute('d','');document.getElementById('navArrow').style.display='none';progress=0;totalSteps=0;}
function filterBuildings(){const q=document.getElementById('searchBox').value.toLowerCase();document.querySelectorAll('.quick-item').forEach(el=>{el.style.display=el.textContent.toLowerCase().includes(q)?'':'none';});}
</script>
</body></html>
